+func (s *Sentinel) evaluateStep(ctx context.Context, step PromotionStep) Decision {
+    // compute rolling metrics and sample hashes
+    metrics := s.metricsWindow(step.window)
+    if metrics.ErrorRate > step.quarantineThresh {
+        return Decision{Action: Quarantine, Reason: "error-rate exceeded"}
+    }
+    // smoke-rewind check
+    if s.runSmokeRewind(ctx, step) {
+        return Decision{Action: Promote}
+    }
+    return Decision{Action: Hold}
+}
